using System.Buffers.Binary;
using System.Text;

namespace FormatStudio.Runtime;

/// <summary>
/// Reads wire primitives from a span for code generated by Format Studio (generator <c>csharp</c>): fixed-width integers
/// in both byte orders, LEB128 varints (plain and zigzag), UUIDs as two 64-bit halves, UTF-8 strings, raw byte arrays
/// and NBT in four flavors (kept as raw bytes).
/// </summary>
public ref struct FormatReader
{
    private const int MaxNbtDepth = 512;

    private readonly ReadOnlySpan<byte> _data;
    private int _position;

    public FormatReader(ReadOnlySpan<byte> data)
    {
        _data = data;
    }

    public readonly int Position => _position;
    public readonly int Length => _data.Length;
    public readonly int Remaining => _data.Length - _position;
    public readonly ReadOnlySpan<byte> RemainingSpan => _data[_position..];

    private ReadOnlySpan<byte> Take(int count)
    {
        if ((uint)count > (uint)Remaining)
            throw new FormatDataException($"Needs {count} bytes at offset {_position}, {Remaining} remaining");
        var span = _data.Slice(_position, count);
        _position += count;
        return span;
    }

    /// <summary>Reads <paramref name="length"/> bytes as a separate reader (a length-delimited section).</summary>
    public FormatReader Slice(int length) => new(Take(length));

    /// <summary>Validates a collection count read from the wire before anything is allocated.</summary>
    public readonly int CheckCount(long count, int minElementSize, int max = int.MaxValue)
    {
        if (count < 0) throw new FormatDataException($"Negative count {count} at offset {_position}");
        if (count > max) throw new FormatDataException($"Count {count} exceeds the maximum of {max} at offset {_position}");
        if (count * Math.Max(minElementSize, 0) > Remaining)
            throw new FormatDataException($"Count {count} needs at least {count * minElementSize} bytes at offset {_position}, {Remaining} remaining");
        return (int)Math.Min(count, int.MaxValue);
    }

    public readonly int CheckCount(ulong count, int minElementSize, int max = int.MaxValue) =>
        CheckCount(count > long.MaxValue ? long.MaxValue : (long)count, minElementSize, max);

    public bool ReadBool() => Take(1)[0] != 0;
    public byte ReadU8() => Take(1)[0];
    public sbyte ReadI8() => (sbyte)Take(1)[0];

    public ushort ReadU16LE() => BinaryPrimitives.ReadUInt16LittleEndian(Take(2));
    public ushort ReadU16BE() => BinaryPrimitives.ReadUInt16BigEndian(Take(2));
    public short ReadI16LE() => BinaryPrimitives.ReadInt16LittleEndian(Take(2));
    public short ReadI16BE() => BinaryPrimitives.ReadInt16BigEndian(Take(2));
    public uint ReadU32LE() => BinaryPrimitives.ReadUInt32LittleEndian(Take(4));
    public uint ReadU32BE() => BinaryPrimitives.ReadUInt32BigEndian(Take(4));
    public int ReadI32LE() => BinaryPrimitives.ReadInt32LittleEndian(Take(4));
    public int ReadI32BE() => BinaryPrimitives.ReadInt32BigEndian(Take(4));
    public ulong ReadU64LE() => BinaryPrimitives.ReadUInt64LittleEndian(Take(8));
    public ulong ReadU64BE() => BinaryPrimitives.ReadUInt64BigEndian(Take(8));
    public long ReadI64LE() => BinaryPrimitives.ReadInt64LittleEndian(Take(8));
    public long ReadI64BE() => BinaryPrimitives.ReadInt64BigEndian(Take(8));
    public float ReadF32LE() => BinaryPrimitives.ReadSingleLittleEndian(Take(4));
    public float ReadF32BE() => BinaryPrimitives.ReadSingleBigEndian(Take(4));
    public double ReadF64LE() => BinaryPrimitives.ReadDoubleLittleEndian(Take(8));
    public double ReadF64BE() => BinaryPrimitives.ReadDoubleBigEndian(Take(8));

    public uint ReadVarUInt32()
    {
        uint result = 0;
        for (var shift = 0; shift < 35; shift += 7)
        {
            var b = ReadU8();
            result |= (uint)(b & 0x7F) << shift;
            if ((b & 0x80) == 0)
            {
                if (shift == 28 && b > 0x0F) throw new FormatDataException($"VarUInt32 overflow at offset {_position - 1}");
                return result;
            }
        }

        throw new FormatDataException($"VarUInt32 longer than 5 bytes at offset {_position}");
    }

    public ulong ReadVarUInt64()
    {
        ulong result = 0;
        for (var shift = 0; shift < 70; shift += 7)
        {
            var b = ReadU8();
            result |= (ulong)(b & 0x7F) << shift;
            if ((b & 0x80) == 0)
            {
                if (shift == 63 && b > 0x01) throw new FormatDataException($"VarUInt64 overflow at offset {_position - 1}");
                return result;
            }
        }

        throw new FormatDataException($"VarUInt64 longer than 10 bytes at offset {_position}");
    }

    /// <summary>Two's complement LEB128 (Java VarInt).</summary>
    public int ReadVarInt32() => (int)ReadVarUInt32();

    public long ReadVarInt64() => (long)ReadVarUInt64();

    /// <summary>Zigzag LEB128 (e.g. the Bedrock "varint").</summary>
    public int ReadZigZag32()
    {
        var value = ReadVarUInt32();
        return (int)(value >> 1) ^ -(int)(value & 1);
    }

    public long ReadZigZag64()
    {
        var value = ReadVarUInt64();
        return (long)(value >> 1) ^ -(long)(value & 1);
    }

    /// <summary>A UUID as two little-endian 64-bit halves, most significant half first.</summary>
    public Guid ReadUuidLE()
    {
        var bytes = Take(16);
        Span<byte> big = stackalloc byte[16];
        BinaryPrimitives.WriteUInt64BigEndian(big, BinaryPrimitives.ReadUInt64LittleEndian(bytes));
        BinaryPrimitives.WriteUInt64BigEndian(big[8..], BinaryPrimitives.ReadUInt64LittleEndian(bytes[8..]));
        return new Guid(big, bigEndian: true);
    }

    /// <summary>A UUID in RFC 4122 byte order (two big-endian 64-bit halves).</summary>
    public Guid ReadUuidBE() => new(Take(16), bigEndian: true);

    public string ReadUtf8(int byteCount) => Encoding.UTF8.GetString(Take(byteCount));

    public string ReadUtf8Zero()
    {
        var end = _data[_position..].IndexOf((byte)0);
        if (end < 0) throw new FormatDataException($"Missing string terminator after offset {_position}");
        var text = Encoding.UTF8.GetString(Take(end));
        _position++;
        return text;
    }

    public byte[] ReadBytes(int count) => Take(count).ToArray();

    /// <summary>Reads one NBT tag (big endian, named root) and returns its raw bytes.</summary>
    public byte[] ReadNbtJava() => ReadNbt(NbtLayout.Java, named: true);

    /// <summary>Reads one NBT tag (big endian, unnamed root) and returns its raw bytes.</summary>
    public byte[] ReadNbtJavaNetwork() => ReadNbt(NbtLayout.Java, named: false);

    /// <summary>Reads one NBT tag (little endian, named root) and returns its raw bytes.</summary>
    public byte[] ReadNbtBedrock() => ReadNbt(NbtLayout.Bedrock, named: true);

    /// <summary>Reads one NBT tag (little endian with varints, named root) and returns its raw bytes.</summary>
    public byte[] ReadNbtBedrockNetwork() => ReadNbt(NbtLayout.BedrockNetwork, named: true);

    private enum NbtLayout
    {
        Java,
        Bedrock,
        BedrockNetwork,
    }

    private byte[] ReadNbt(NbtLayout layout, bool named)
    {
        var start = _position;
        var type = ReadU8();
        if (type != 0)
        {
            if (named) SkipNbtString(layout);
            SkipNbtPayload(layout, type, 0);
        }

        return _data[start.._position].ToArray();
    }

    private void SkipNbtString(NbtLayout layout) => Take(layout switch
    {
        NbtLayout.Java => ReadU16BE(),
        NbtLayout.Bedrock => ReadU16LE(),
        _ => CheckCount(ReadVarUInt32(), 1),
    });

    private int ReadNbtLength(NbtLayout layout, int elementSize) => CheckCount(layout switch
    {
        NbtLayout.Java => ReadI32BE(),
        NbtLayout.Bedrock => ReadI32LE(),
        _ => ReadZigZag32(),
    }, elementSize);

    private void SkipNbtPayload(NbtLayout layout, byte type, int depth)
    {
        if (depth > MaxNbtDepth) throw new FormatDataException("NBT nested too deeply");
        var network = layout == NbtLayout.BedrockNetwork;
        switch (type)
        {
            case 1: Take(1); break;
            case 2: Take(2); break;
            case 3: if (network) ReadZigZag32(); else Take(4); break;
            case 4: if (network) ReadZigZag64(); else Take(8); break;
            case 5: Take(4); break;
            case 6: Take(8); break;
            case 7: Take(ReadNbtLength(layout, 1)); break;
            case 8: SkipNbtString(layout); break;
            case 9:
                var elementType = ReadU8();
                var count = ReadNbtLength(layout, 0);
                for (var i = 0; i < count; i++) SkipNbtPayload(layout, elementType, depth + 1);
                break;
            case 10:
                while (true)
                {
                    var childType = ReadU8();
                    if (childType == 0) break;
                    SkipNbtString(layout);
                    SkipNbtPayload(layout, childType, depth + 1);
                }

                break;
            case 11:
                var ints = ReadNbtLength(layout, network ? 1 : 4);
                for (var i = 0; i < ints; i++) SkipNbtPayload(layout, 3, depth + 1);
                break;
            case 12:
                var longs = ReadNbtLength(layout, network ? 1 : 8);
                for (var i = 0; i < longs; i++) SkipNbtPayload(layout, 4, depth + 1);
                break;
            default:
                throw new FormatDataException($"Unknown NBT tag type {type} at offset {_position - 1}");
        }
    }
}
